import{_ as o,o as t,c as n,a2 as a}from"./chunks/framework.Cdp8-jB6.js";const u=JSON.parse('{"title":"ADR-093 — Journey instrumentation, event naming for Umami reports, and no session replay","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-093.md","filePath":"adr/ADR-093.md"}'),r={name:"adr/ADR-093.md"};function s(i,e,d,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-093-—-journey-instrumentation-event-naming-for-umami-reports-and-no-session-replay" tabindex="-1">ADR-093 — Journey instrumentation, event naming for Umami reports, and no session replay <a class="header-anchor" href="#adr-093-—-journey-instrumentation-event-naming-for-umami-reports-and-no-session-replay" aria-label="Permalink to &quot;ADR-093 — Journey instrumentation, event naming for Umami reports, and no session replay&quot;">​</a></h1><blockquote><p>Status · Accepted · 2026-09-10 · Operator-directed · builds on <strong>ADR-081</strong> (self-hosted Umami) and <strong>ADR-092</strong> (opt-out + privacy posture) · consumption runbook: <a href="./../guides/analytics-consuming-events"><code>docs/guides/analytics-consuming-events.md</code></a></p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The event registry answered &quot;what is popular&quot; and could not answer &quot;did the visitor get anywhere&quot;. Three holes were concrete:</p><ul><li><strong><code>/plan</code> emitted only two <code>filter-change</code> events.</strong> It was impossible to tell whether the trajectory planner had ever been <em>used</em>, as opposed to opened.</li><li><strong><code>/fly</code> emitted a start and an end</strong> (<code>mission-load</code>, <code>mission-complete</code>) with nothing between, so &quot;where do visitors stop&quot; was unanswerable.</li><li><strong><code>science-section-view</code> carried no provenance</strong>, so &quot;did exploring Mars lead to reading about it&quot; was unanswerable.</li></ul><p>Separately, an audit of the live prod database found <strong><code>app-load</code> had fired 0 times against 731 <code>route-enter</code>s</strong> — see Decision 4.</p><p>The instance is <strong>Umami 3.3.0</strong>, which offers funnel, journey, retention, goals, heatmap, breakdown, attribution, UTM, performance and revenue reports.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><h3 id="_1-six-journey-events-milestone-deduped" tabindex="-1">1. Six journey events, milestone-deduped <a class="header-anchor" href="#_1-six-journey-events-milestone-deduped" aria-label="Permalink to &quot;1. Six journey events, milestone-deduped&quot;">​</a></h3><p><code>explore-depth</code>, <code>plan-run</code>, <code>plan-window-select</code>, <code>fly-&lt;act&gt;</code>, <code>science-to-app</code>, <code>tour-complete</code>, plus a <code>source</code> property on <code>science-section-view</code>.</p><p>Every one fires on <strong>first reach</strong> and never on a repeat: a re-render, a timeline scrub, or walking back down the scale ladder must not inflate a funnel. Dedup keys live in <strong>module-level in-memory state</strong>, not a cookie and not storage — ADR-057 bans client storage and ADR-092 spent the third cookie. Module scope survives SPA navigation and dies on reload, which is the correct lifetime: a genuine return visit should count again.</p><p><code>tour-complete</code> fires from <code>nextTourId()</code> reaching the end of the sequence, and deliberately <strong>not</strong> from <code>stopTour()</code>, which is abandonment. Mixing the two would make the completion rate meaningless.</p><p><code>plan-window-select</code> fires only on a <strong>deliberate</strong> pick (pointer or the touch magnifier). The auto-selected &quot;cheapest viable&quot; default and the <code>?dep</code>/<code>?tof</code> deep-link restore do not fire it — counting those would make <code>plan-window-select ÷ plan-run</code> meaningless.</p><h3 id="_2-kebab-case-event-names-snake-case-properties" tabindex="-1">2. Kebab-case event names; snake_case properties <a class="header-anchor" href="#_2-kebab-case-event-names-snake-case-properties" aria-label="Permalink to &quot;2. Kebab-case event names; snake_case properties&quot;">​</a></h3><p>Unchanged from the existing registry, and enforced by the <code>analytics.test.ts</code> guard (<code>/^[a-z][a-z0-9-]*$/</code>). An outside proposal recommended snake_case event names; adopting it would have failed that test and split the dashboard vocabulary. Rejected.</p><h3 id="_3-one-event-name-per-fly-act-—-the-deliberate-exception" tabindex="-1">3. One event NAME per <code>/fly</code> act — the deliberate exception <a class="header-anchor" href="#_3-one-event-name-per-fly-act-—-the-deliberate-exception" aria-label="Permalink to &quot;3. One event NAME per `/fly` act — the deliberate exception&quot;">​</a></h3><p><strong>Umami&#39;s Funnel, Journey and Goal steps match on an event <em>name</em> or a URL. There is no property condition in the step form</strong> (<a href="https://docs.umami.is/docs/funnel" target="_blank" rel="noreferrer">docs</a>). A single <code>fly-phase</code> event carrying <code>phase=cruise</code> would therefore collapse into one indistinguishable funnel step.</p><p>So <code>/fly</code> emits <code>fly-ascent</code>, <code>fly-coast</code>, <code>fly-cruise</code>, <code>fly-descent</code>, <code>fly-recovery</code>, with <code>mission</code> and <code>dest</code> as properties. This inverts the otherwise-correct &quot;stable vocabulary + properties, never one event per value&quot; rule, and the reason is specifically Umami&#39;s step matcher.</p><p><code>explore-depth</code> keeps the <code>level</code> property rather than splitting into eight names: the scale ladder is strictly monotonic, so the Properties breakdown gives the same drop-off curve and eight names would bloat the registry for no new answer.</p><h3 id="_4-track-buffers-events-fired-before-the-tracker-script-loads" tabindex="-1">4. <code>track()</code> buffers events fired before the tracker script loads <a class="header-anchor" href="#_4-track-buffers-events-fired-before-the-tracker-script-loads" aria-label="Permalink to &quot;4. `track()` buffers events fired before the tracker script loads&quot;">​</a></h3><p><code>+layout.svelte</code> calls <code>initAnalytics()</code> — which appends a <code>&lt;script defer&gt;</code> — and then <code>track(&#39;app-load&#39;, …)</code> on the next line. The deferred script has not executed, so <code>window.umami</code> was <code>undefined</code> and <strong>every <code>app-load</code> since launch evaporated</strong>. The module claimed events were &quot;safe before the script loads (it queues)&quot;; that was false — Umami&#39;s queue only exists once its own script defines the global.</p><p><code>track()</code> now buffers into a capped (50) in-memory queue and flushes in order on the script&#39;s <code>load</code> event. Without this, the six new milestone events would have inherited the same flaw: <code>explore-depth</code> fires from an effect at mount and <code>plan-run</code> on the first grid load.</p><h3 id="_5-no-session-replay-therefore-no-heatmaps" tabindex="-1">5. No session replay, therefore no heatmaps <a class="header-anchor" href="#_5-no-session-replay-therefore-no-heatmaps" aria-label="Permalink to &quot;5. No session replay, therefore no heatmaps&quot;">​</a></h3><p>Umami 3.3 supports heatmaps, but they are driven by the session recorder. <strong>We are not enabling it.</strong> Doing so would require a website setting, a different tracker script (<code>/recorder.js</code>), a new path in <code>ops/caddy/orrery-analytics.caddy</code> (which allowlists exactly <code>/script.js</code> and <code>/api/send</code>), and replacing <code>frame-ancestors &#39;none&#39;</code> with the Umami origin in <code>ops/docker/nginx.conf</code>.</p><p>Session replay is a materially different category of collection from counting events; <code>/privacy</code> currently describes something narrower; and the CSP change loosens a header set to <code>none</code> on purpose. Revisit only with an ADR amendment and a <code>/privacy</code> copy change.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive</strong></p><ul><li>The three previously-unanswerable questions become answerable, and the <code>/plan</code> and <code>/fly</code> funnels work natively in Umami&#39;s own UI with no SQL.</li><li><code>sourceRoute()</code> gives any future event free provenance — the value already flowed through <code>route-enter</code>&#39;s <code>from_route</code>.</li><li>The pre-load buffer fixes a silent data-loss bug that predates this work.</li></ul><p><strong>Negative</strong></p><ul><li><code>fly-*</code> breaks the one-name-many-properties convention, and a future act added to the state machine needs a matching entry in <code>FLY_ACT_EVENT</code> or it silently won&#39;t report. Mitigated by a test asserting the full act→name map.</li><li>Registry growth: 24 → 34 event names.</li><li>Milestone dedup is per page-load, so session-scoped rates still need <code>count(distinct session_id)</code> in SQL rather than raw event counts.</li></ul><p><strong>Neutral</strong></p><ul><li>No change to the env ladder (ADR-082), the opt-out gate (ADR-092), or the edge vhost. Every new event routes through the same suppressed-when-opted-out <code>track()</code>.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>A <code>fly-phase</code> event with a <code>phase</code> property.</strong> Tidier vocabulary; cannot be funnelled in Umami. Rejected once the docs made the step matcher explicit — this was originally implemented the tidy way and changed after reading them.</li><li><strong>Splitting <code>explore-depth</code> into eight names too.</strong> Rejected: monotonic ladder, breakdown is equivalent, registry cost is real.</li><li><strong>A polling flush for the pre-load buffer.</strong> Rejected in favour of the script&#39;s <code>load</code> event — deterministic, no timer.</li></ul><h2 id="not-covered-out-of-scope" tabindex="-1">Not covered / out of scope <a class="header-anchor" href="#not-covered-out-of-scope" aria-label="Permalink to &quot;Not covered / out of scope&quot;">​</a></h2><ul><li><strong>Translations</strong> of the ADR-092 <code>/privacy</code> strings remain outstanding (en-US ships, 13 locales fall back).</li><li><strong>No e2e coverage</strong> for any journey event or the opt-out toggle. Unit tests cover the dedup and the buffer; nothing has exercised them in a browser.</li><li><strong>Umami-side reports are not version-controlled</strong> — they live in the Umami database. <code>ops/observability/dashboards/orrery-analytics.json</code> mirrors the key metrics in Grafana precisely because that <em>is</em> version-controlled, but it is a secondary surface, not the primary one.</li></ul>',36)])])}const m=o(r,[["render",s]]);export{u as __pageData,m as default};
